package vn.covie.checkout.application; import java.util.*; import org.springframework.stereotype.Component; import vn.covie.checkout.model.CheckoutSourceType; @Component public class CheckoutCandidateResolverRegistry{private final Map<CheckoutSourceType,CheckoutCandidateResolver> resolvers;public CheckoutCandidateResolverRegistry(List<CheckoutCandidateResolver> values){Map<CheckoutSourceType,CheckoutCandidateResolver> map=new EnumMap<>(CheckoutSourceType.class);for(var v:values)if(map.put(v.supports(),v)!=null)throw new IllegalStateException("Duplicate checkout resolver");resolvers=Map.copyOf(map);}public CheckoutCandidate resolve(java.util.UUID user,vn.covie.checkout.api.dto.CheckoutPreviewRequest request){var r=resolvers.get(request.sourceType());if(r==null)throw new IllegalArgumentException("Unsupported checkout source");return r.resolve(user,request);}}
